  function homeInteractions(){return `<section class="home-playground" aria-labelledby="playgroundTitle"><div class="section-heading"><div><span class="eyebrow">INTERACTIVE LAB</span><h2 id="playgroundTitle">Make your next move</h2></div><p>Three quick tools that turn browsing into a learning decision.</p></div><div class="playground-grid"><article class="path-finder"><div class="playground-icon">${icon('search')}</div><span>PATH FINDER</span><h3>What do you want to build?</h3><div class="finder-options" role="group" aria-label="Choose a learning goal"><button data-find-path="react">Interactive interfaces</button><button data-find-path="spring-boot">Production APIs</button><button data-find-path="java-essentials">Strong programming foundations</button><button data-find-path="projects">Portfolio projects</button></div><div class="finder-result" id="finderResult" aria-live="polite"><small>Choose a goal</small><strong>Your recommended path appears here.</strong></div></article><article class="challenge-machine"><div class="playground-icon">${icon('projects')}</div><span>CHALLENGE DECK</span><h3>Draw a practical challenge</h3><div class="challenge-card" id="challengeCard"><small>CHALLENGE 01</small><strong>Build a lesson progress component that persists after refresh.</strong><p>Focus: state, storage, and accessible controls.</p></div><button class="playground-action" id="nextChallenge" type="button">${icon('next')}<span>Draw another</span></button></article><article class="study-planner"><div class="playground-icon">${icon('notes')}</div><span>STUDY PLANNER</span><h3>Plan your weekly pace</h3><label for="weeklyHours"><span>Hours per week</span><strong id="weeklyHoursValue">6h</strong></label><input id="weeklyHours" type="range" min="2" max="20" value="6" step="1" aria-label="Hours per week" aria-describedby="weeklyHoursValue plannerWeeks"><div class="planner-result"><strong id="plannerWeeks">10</strong><span>weeks for a focused 60-hour path</span></div><div class="planner-bars" aria-hidden="true"><i></i><i></i><i></i><i></i><i></i></div></article></div></section>`;}
  function setupHomeInteractions(){const insights=$('.home-insights');if(!insights||$('.home-playground'))return;insights.insertAdjacentHTML('beforebegin',homeInteractions());$$('[data-find-path]').forEach(button=>button.addEventListener('click',()=>{const course=courses[button.dataset.findPath],result=$('#finderResult');$$('[data-find-path]').forEach(item=>item.classList.toggle('active',item===button));result.style.setProperty('--result-color',course.color);result.innerHTML=`<small>RECOMMENDED PATH</small><strong>${esc(course.title)}</strong><a href="${routeHref(course.id)}">Open course ${icon('next')}</a>`;}));const challenges=[['Build a lesson progress component that persists after refresh.','State, storage, and accessible controls.'],['Design an API endpoint with validation and useful error responses.','Contracts, validation, and failure paths.'],['Refactor repeated UI into three reusable components.','Composition, props, and maintainability.'],['Model a course catalog with filtering and search.','Collections, data flow, and performance.'],['Write tests for a bookmark toggle and saved note.','Behavior, edge cases, and confidence.']];let challengeIndex=0;$('#nextChallenge')?.addEventListener('click',()=>{challengeIndex=(challengeIndex+1)%challenges.length;const card=$('#challengeCard'),[title,focus]=challenges[challengeIndex];card.classList.remove('swap');void card.offsetWidth;card.classList.add('swap');card.innerHTML=`<small>CHALLENGE ${String(challengeIndex+1).padStart(2,'0')}</small><strong>${title}</strong><p>Focus: ${focus}</p>`;});const updatePlanner=()=>{const hours=Number($('#weeklyHours')?.value||6),weeks=Math.ceil(60/hours);$('#weeklyHoursValue').textContent=`${hours}h`;$('#plannerWeeks').textContent=String(weeks);$$('.planner-bars i').forEach((bar,index)=>bar.style.setProperty('--bar',`${Math.min(100,(hours/20*100)+(index*4))}%`));};$('#weeklyHours')?.addEventListener('input',updatePlanner);updatePlanner();}
