    return `<article class="course-card" data-type="${type}" style="--course:${course.color}"><div class="course-card-top"><span class="tech-icon">${technologyIcon(course)}</span><span class="course-level">${course.level}</span></div><h3>${esc(course.title)}</h3><p>${esc(course.description)}</p><div class="course-meta"><span>${p.total} lessons</span><span>${course.duration}</span></div><div class="card-progress"><div><span>Progress</span><strong>${p.percent}%</strong></div><progress max="100" value="${p.percent}">${p.percent}%</progress></div><a href="${routeHref(course.id)}">${p.done?'Continue course':'Explore course'} <span aria-hidden="true">→</span></a></article>`;
